  const id=randomUUID();await client.query(`INSERT INTO delivery_technical_acceptances(id,package_id,content_hash,delivery_revision,normative_generation,assurance_dispatch_snapshot_id,work_acceptance_id,state,acceptance_key) VALUES($1,$2,$3,$4,$5,$6,$7,'ACCEPTED',$8)`,[id,packageId,pkg.content_hash,pkg.delivery_revision,pkg.normative_generation,dispatch,acceptance,key]);await event(client,pkg.project_id,'RELEASE_TECHNICALLY_ACCEPTED',{package_id:packageId,content_hash:pkg.content_hash,delivery_revision:pkg.delivery_revision,normative_generation:pkg.normative_generation,acceptance_id:id});return (await client.query(`SELECT * FROM delivery_technical_acceptances WHERE id=$1`,[id])).rows[0];
