  const evidence=requireObject(gate.evidence,'DELIVERY_GATE_EVIDENCE_INVALID'),pkg=(await client.query(`SELECT * FROM delivery_packages WHERE id=$1 FOR UPDATE`,[evidence.package_id])).rows[0];if(!pkg||pkg.stale_at||pkg.content_hash!==evidence.content_hash||Number(pkg.delivery_revision)!==Number(evidence.delivery_revision)||pkg.normative_generation!==evidence.normative_generation)throw new ApiError(409,'STALE_DELIVERY_PACKAGE');await assertCurrentDeliveryPackage(client,pkg);const technical=(await client.query(`SELECT * FROM delivery_technical_acceptances WHERE id=$1 FOR UPDATE`,[evidence.acceptance_id])).rows[0];if(!technical||technical.state!=='ACCEPTED'||technical.package_id!==pkg.id||technical.content_hash!==pkg.content_hash||Number(technical.delivery_revision)!==Number(pkg.delivery_revision)||technical.normative_generation!==pkg.normative_generation)throw new ApiError(409,'TECHNICAL_ACCEPTANCE_REQUIRED');
  if(input.decision==='REWORK'){if(!Object.keys(requireObject(input.evidence,'DELIVERY_REWORK_FINDING_REQUIRED')).length)throw new ApiError(422,'DELIVERY_REWORK_FINDING_REQUIRED');const decisionId=randomUUID();await client.query(`INSERT INTO gate_decisions(id,gate_id,catalog_version,gate_version,decision,actor_id,actor_role,reason,evidence,idempotency_key) VALUES($1,$2,$3,$4,'REWORK',$5,$6,$7,$8,$9)`,[decisionId,gate.id,gate.catalog_version,gate.version,input.actor_id,input.actor_role,input.reason,input.evidence,input.idempotency_key]);await client.query(`UPDATE gate_records SET status='DECIDED',decision='REWORK',decision_id=$2,decided_at=clock_timestamp(),version=version+1 WHERE id=$1`,[gate.id,decisionId]);await client.query(`UPDATE delivery_packages SET stale_at=clock_timestamp(),stale_reason='DELIVERY_REWORK' WHERE id=$1`,[pkg.id]);await client.query(`UPDATE projects SET state='VALIDATION',updated_at=clock_timestamp() WHERE id=$1`,[projectId]);await event(client,projectId,'DELIVERY_REWORK_REQUESTED',{package_id:pkg.id,gate_id:gate.id,decision_id:decisionId},input.actor_id);return {project_id:projectId,state:'VALIDATION',gate_id:gate.id};}
  const members=array(pkg.participants,'DELIVERY_PACKAGE_PARTICIPANTS_INVALID') as any[],ids=members.map(m=>String(m.module_id)).sort();if(new Set(ids).size!==ids.length)throw new ApiError(409,'DELIVERY_PACKAGE_PARTICIPANTS_INVALID');const current=await requiredParticipants(client,projectId);if(!same(frozenMembers(current),pkg.committed_module_set)||current.some((r:any)=>!ids.includes(String(r.module_id)))||ids.length!==current.length)throw new ApiError(409,'DELIVERY_REQUIRED_SET_STALE');
